mapper.select:
SELECT ci.id, ci.cert_no AS certNo, ci.strategy_id AS strategyId, cs.strategy_name AS strategyName, cs.spec_type AS specType, ci.issue_date AS issueDate, ci.status FROM cert_info ci LEFT JOIN cert_strategy cs ON ci.strategy_id = cs.id
AND ci.status = #{status}
ORDER BY ci.issue_date DESC, ci.id DESC
